**Approach:** parse the version with a strict `\d+\.\d+\.\d+` regex into an integer tuple, then tokenize the spec on whitespace. Each token is an optional operator (`>=`, `<=`, `>`, `<`, `=`, `^`, `~`) followed by a version; a bare version means exact equality. Caret/tilde tokens expand into lower/upper bounds, and every token must hold (conjunction). Anything that doesn't match the grammar raises `ValueError`.

```python
import re
from typing import List, Tuple

_VERSION_RE = re.compile(r'^(\d+)\.(\d+)\.(\d+)$')
_TOKEN_RE = re.compile(r'^(>=|<=|>|<|=|\^|~)?(\d+\.\d+\.\d+)$')


def _parse_version(text: str) -> Tuple[int, int, int]:
    if not isinstance(text, str):
        raise ValueError("version must be a string: %r" % (text,))
    m = _VERSION_RE.match(text.strip())
    if not m:
        raise ValueError("malformed version: %r" % (text,))
    return (int(m.group(1)), int(m.group(2)), int(m.group(3)))


def satisfies(version: str, spec: str) -> bool:
    """Return True if `version` satisfies `spec`.

    spec may be an exact version ('1.2.3'), a caret range ('^1.2.3'),
    a tilde range ('~1.2.3'), or a space-separated conjunction of
    comparators ('>=1.0.0 <2.0.0').  Raises ValueError if either the
    version or the spec is malformed.
    """
    v = _parse_version(version)

    if not isinstance(spec, str):
        raise ValueError("spec must be a string: %r" % (spec,))
    tokens = spec.split()
    if not tokens:
        raise ValueError("malformed spec: %r" % (spec,))

    # Build a list of (operator, version-tuple) constraints.
    constraints: List[Tuple[str, Tuple[int, int, int]]] = []
    for tok in tokens:
        m = _TOKEN_RE.match(tok)
        if not m:
            raise ValueError("malformed spec: %r" % (spec,))
        op = m.group(1) or '='
        base = _parse_version(m.group(2))
        major, minor, patch = base

        if op == '^':
            if major > 0:
                upper = (major + 1, 0, 0)
            elif minor > 0:
                upper = (0, minor + 1, 0)
            else:
                upper = (0, 0, patch + 1)
            constraints.append(('>=', base))
            constraints.append(('<', upper))
        elif op == '~':
            constraints.append(('>=', base))
            constraints.append(('<', (major, minor + 1, 0)))
        else:
            constraints.append((op, base))

    for op, target in constraints:
        if op == '=':
            ok = v == target
        elif op == '>':
            ok = v > target
        elif op == '>=':
            ok = v >= target
        elif op == '<':
            ok = v < target
        elif op == '<=':
            ok = v <= target
        else:  # pragma: no cover - unreachable given the regex
            raise ValueError("malformed spec: %r" % (spec,))
        if not ok:
            return False
    return True
